/// Choice placeholder in a rotary steerable tool.
///
/// Abstract in the schema: the concrete subtype is selected by `xsi:type`.
#[derive(Debug, Clone, PartialEq, EnergymlChoice)]
#[energyml(
    package = "witsml",
    version = "2.1",
    xml_name = "AbstractRotarySteerableTool",
    abstract_type
)]
pub enum AbstractRotarySteerableTool {
    #[energyml(xsi_type = "witsml:BendAngle", xml_name = "BendAngle")]
    BendAngle(BendAngle),

    #[energyml(xsi_type = "witsml:BendOffset", xml_name = "BendOffset")]
    BendOffset(BendOffset),

}

/// Tubular Connection Component Schema. Describes dimensions and properties of a connection between tubulars.
///
/// `Connection` is concrete and other types extend it, so a document may write any of them here, selected by `xsi:type`. The `Connection` variant is the declared type and is written without one.
#[derive(Debug, Clone, PartialEq, EnergymlChoice)]
#[energyml(
    package = "witsml",
    version = "2.1",
    xml_name = "Connection"
)]
pub enum AnyConnection {
    #[energyml(xsi_type = "witsml:Connection", xml_name = "Connection", implicit)]
    Connection(Connection),

    #[energyml(xsi_type = "witsml:EquipmentConnection", xml_name = "EquipmentConnection")]
    EquipmentConnection(EquipmentConnection),

}

