/// Bit Record Component Schema. Captures information that describes the bit and problems with the bit. Many of the problems are classified using IADC codes that are specified as enumerated lists in WITSML.
#[derive(Debug, Default, Clone, PartialEq, EnergymlObject)]
#[energyml(
    package = "witsml",
    version = "2.1",
    xml_name = "BitRecord"
)]
pub struct BitRecord {
    /// Bit number and rerun number, e.g., "4.1" for the first rerun of bit 4.
    #[energyml(elem, xml_name = "NumBit", max_length = 64)]
    pub num_bit: Option<String>,

    /// Diameter of the drilled hole.
    #[energyml(elem, xml_name = "DiaBit")]
    pub dia_bit: energyml_eml_2_3::LengthMeasure,

    /// Minimum hole or tubing diameter that the bit will pass through (for bi-center bits).
    #[energyml(elem, xml_name = "DiaPassThru")]
    pub dia_pass_thru: Option<energyml_eml_2_3::LengthMeasure>,

    /// Diameter of the pilot bit (for bi-center bits).
    #[energyml(elem, xml_name = "DiaPilot")]
    pub dia_pilot: Option<energyml_eml_2_3::LengthMeasure>,

    /// Pointer to a BusinessAssociate representing the manufacturer or supplier of the item.
    #[energyml(elem, xml_name = "Manufacturer")]
    pub manufacturer: Option<energyml_eml_2_3::DataObjectReference>,

    /// Type of bit.
    #[energyml(elem, xml_name = "TypeBit")]
    pub type_bit: Option<BitType>,

    /// The manufacturer's code for the bit.
    #[energyml(elem, xml_name = "CodeMfg", max_length = 64)]
    pub code_mfg: Option<String>,

    /// IADC bit code.
    #[energyml(elem, xml_name = "CodeIADC", max_length = 64)]
    pub code_iadc: Option<String>,

    /// Initial condition of the inner tooth rows (inner 2/3 of the bit) (0-8).
    #[energyml(elem, xml_name = "CondInitInner")]
    pub cond_init_inner: Option<IadcIntegerCode>,

    /// Initial condition of the outer tooth rows (outer 1/3 of bit) (0-8).
    #[energyml(elem, xml_name = "CondInitOuter")]
    pub cond_init_outer: Option<IadcIntegerCode>,

    /// Initial dull condition from the IADC bit-wear 2-character codes.
    #[energyml(elem, xml_name = "CondInitDull")]
    pub cond_init_dull: Option<BitDullCode>,

    /// Initial row and cone numbers for items that need location information (e.g., cracked cone, lost cone, etc).
    #[energyml(elem, xml_name = "CondInitLocation", max_length = 64)]
    pub cond_init_location: Option<String>,

    /// Initial condition of the bit bearings (integer 0-8 or E, F, N or X).
    #[energyml(elem, xml_name = "CondInitBearing")]
    pub cond_init_bearing: Option<IadcBearingWearCode>,

    /// Initial condition of the bit gauge in 1/16 of an inch. I = in gauge, else the number of 16ths out of gauge.
    #[energyml(elem, xml_name = "CondInitGauge", max_length = 64)]
    pub cond_init_gauge: Option<String>,

    /// Other comments on initial bit condition from the IADC list (BitDullCode enumerated list).
    #[energyml(elem, xml_name = "CondInitOther", max_length = 64)]
    pub cond_init_other: Option<String>,

    /// Initial reason the bit was pulled from IADC codes (BitReasonPulled enumerated list).
    #[energyml(elem, xml_name = "CondInitReason")]
    pub cond_init_reason: Option<BitReasonPulled>,

    /// Final condition of the inner tooth rows (inner 2/3 of bit) (0-8).
    #[energyml(elem, xml_name = "CondFinalInner")]
    pub cond_final_inner: Option<IadcIntegerCode>,

    /// Final condition of the outer tooth rows (outer 1/3 of bit) (0-8).
    #[energyml(elem, xml_name = "CondFinalOuter")]
    pub cond_final_outer: Option<IadcIntegerCode>,

    /// Final dull condition from the IADC bit-wear 2-character codes.
    #[energyml(elem, xml_name = "CondFinalDull")]
    pub cond_final_dull: Option<BitDullCode>,

    /// Final conditions for row and cone numbers for items that need location information (e.g., cracked cone, lost cone, etc).
    #[energyml(elem, xml_name = "CondFinalLocation", max_length = 64)]
    pub cond_final_location: Option<String>,

    /// Final condition of the bit bearings (integer 0-8 or E, F, N or X).
    #[energyml(elem, xml_name = "CondFinalBearing")]
    pub cond_final_bearing: Option<IadcBearingWearCode>,

    /// Final condition of the bit gauge in 1/16 of a inch. I = in gauge, else number of 16ths out of gauge.
    #[energyml(elem, xml_name = "CondFinalGauge", max_length = 64)]
    pub cond_final_gauge: Option<String>,

    /// Other final comments on bit condition from the IADC list (BitDullCode enumerated list).
    #[energyml(elem, xml_name = "CondFinalOther", max_length = 64)]
    pub cond_final_other: Option<String>,

    /// Final reason the bit was pulled from IADC codes (BitReasonPulled enumerated list).
    #[energyml(elem, xml_name = "CondFinalReason")]
    pub cond_final_reason: Option<BitReasonPulled>,

    /// Bit drive type (motor, rotary table, etc.).
    #[energyml(elem, xml_name = "Drive", max_length = 64)]
    pub drive: Option<String>,

    /// N = new, U = used.
    #[energyml(elem, xml_name = "BitClass", max_length = 64)]
    pub bit_class: Option<String>,

    /// Extensions to the schema based on a name-value construct.
    #[energyml(elem, xml_name = "ExtensionNameValue")]
    pub extension_name_value: Vec<energyml_eml_2_3::ExtensionNameValue>,

    #[energyml(elem, xml_name = "Cost")]
    pub cost: Option<energyml_eml_2_3::Cost>,

    /// Unique identifier for this instance of BitRecord.
    #[energyml(attr, xml_name = "uid", max_length = 64)]
    pub uid: String,

}

